276			r.DecidedAt = timeJSON(time.Time{})
277			r.ReservedAt = timeJSON(t0)
278			r.ReserveDuration = durationJSON(2 * time.Hour)
279			r.ReserveDeadline = timeJSON(t0.Add(2 * time.Hour))
280		})
281		w2, err := restoreAt(data, t0.Add(48*time.Hour))
282		if err != nil {
283			t.Fatalf("reserved-then-cancelled request must restore: %v", err)
284		}
285		r, err := w2.Request("u1", "big")
286		if err != nil {
287			t.Fatal(err)
288		}
289		if r.State != RequestCancelled {
290			t.Fatalf("state = %v, want cancelled", r.State)
291		}
292		if !r.ReservedAt.Equal(t0) || !r.DecidedAt.IsZero() {
293			t.Fatalf("reserved-origin cancellation rewritten: %+v", r)
294		}
295		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
296			t.Fatalf("payer balance = %+v, want untouched", bal)
297		}
298	}
