321	}
322	
323	// TestRestoreReservationExpiredUnaffectedByExpirationTiming 验证已预留费用的
324	// 预留超时不适用待审批过期的时限核对：其等待截止字段本就不存在，仍按既有
325	// 预留超时规则恢复。
326	func TestRestoreReservationExpiredUnaffectedByExpirationTiming(t *testing.T) {
327		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
328		// 未超门槛直接预留（费用 5 ≤ 门槛 10），提交时刻 t0 即完成预留、预留
329		// 时长 2h，截止时刻 t0+2h 超时全额退回。
330		data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
331			r.EstimatedFee = 5
332			r.State = int(RequestReservationExpired)
333			r.WaitDeadline = timeJSON(time.Time{})
334			r.DecidedAt = timeJSON(time.Time{})
335			r.ReservedAt = timeJSON(t0)
336			r.ReserveDuration = durationJSON(2 * time.Hour)
337			r.ReserveDeadline = timeJSON(t0.Add(2 * time.Hour))
338			r.ReserveExpiredAt = timeJSON(t0.Add(2 * time.Hour))
339		})
340		w2, err := restoreAt(data, t0.Add(48*time.Hour))
341		if err != nil {
342			t.Fatalf("reservation-expired request must restore: %v", err)
343		}
344		r, err := w2.Request("u1", "big")
345		if err != nil {
