4		"encoding/json"
5		"errors"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// buildDeactivatedPendingBackup 构造一个正常流程无法产生的矛盾备份：
12	// 策略 p 已停用，但其下存在一笔仍处于待审批状态的请求 r1。除这处矛盾外，
13	// 其余字段（账户与会话引用、审批门槛、等待截止时刻、金额）全部自洽合法。
14	// withOtherLegalRecords 为 true 时再加入一条未停用策略 p2 及其合法已预留
15	// 请求，验证“其他记录合法”不能让冲突被忽略。
16	func buildDeactivatedPendingBackup(t *testing.T, t0 time.Time, withOtherLegalRecords bool) []byte {
17		t.Helper()
18		created := t0.Add(-time.Minute)
19		b := backupV1{
20			Version:    backupVersion,
21			ExportedAt: timeJSON(t0),
22			Accounts: []accountBackupV1{
23				{ID: "payer", Available: 100, Reserved: 0, CreatedAt: timeJSON(t0)},
24				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
25			},
26			Sessions: []sessionBackupV1{
27				{ID: "s1", AccountID: "u1", DeviceID: "dev1", ExpiresAt: timeJSON(t0.Add(time.Hour)), CreatedAt: timeJSON(t0)},
28				{ID: "sa", AccountID: "payer", DeviceID: "deva", ExpiresAt: timeJSON(t0.Add(2 * time.Hour)), CreatedAt: timeJSON(t0)},
29			},
30			Policies: []policyBackupV1{{
31				ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
32				Operation: "charge", Payee: "shop",
33				StartsAt:             timeJSON(t0.Add(-time.Hour)),
34				EndsAt:               timeJSON(t0.Add(time.Hour)),
35				MaxPerRequest:        100,
36				MaxTotal:             1000,
37				ApprovalThreshold:    10,
38				ApprovalWait:         durationJSON(5 * time.Minute),
39				Deactivated:          true,
40				DeactivatedAt:        timeJSON(t0.Add(-2 * time.Minute)),
41				DeactivatorAccountID: "payer",
42				DeactivateReason:     "stop it",
43			}},
44			Requests: []requestBackupV1{{
45				PolicyID: "p", RequestID: "r1", AccountID: "u1", PayerAccountID: "payer",
46				SessionID: "s1", Operation: "charge", Payee: "shop",
47				EstimatedFee: 20,
48				State:        int(RequestPendingApproval),
49				CreatedAt:    timeJSON(created),
50				// 与提交时刻 + 5 分钟等待时长一致，通过等待期限核对。
51				WaitDeadline: timeJSON(created.Add(5 * time.Minute)),
52			}},
53			Ledger: []ledgerEntryBackupV1{},
54		}
55		if withOtherLegalRecords {
56			b.Policies = append(b.Policies, policyBackupV1{
57				ID: "p2", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
58				Operation: "charge", Payee: "shop",
59				StartsAt:      timeJSON(t0.Add(-time.Hour)),
60				EndsAt:        timeJSON(t0.Add(time.Hour)),
61				MaxPerRequest: 100,
62				MaxTotal:      1000,
63				ReservedTotal: 5,
64			})
65			b.Requests = append(b.Requests, requestBackupV1{
66				PolicyID: "p2", RequestID: "r2", AccountID: "u1", PayerAccountID: "payer",
67				SessionID: "s1", Operation: "charge", Payee: "shop",
68				EstimatedFee: 5,
69				State:        int(RequestReserved),
70				CreatedAt:    timeJSON(t0),
71				ReservedAt:   timeJSON(t0),
72			})
73			for i := range b.Accounts {
74				if b.Accounts[i].ID == "payer" {
75					b.Accounts[i].Available = 95
76					b.Accounts[i].Reserved = 5
77				}
78			}
79		}
80		data, err := json.Marshal(&b)
81		if err != nil {
82			t.Fatal(err)
83		}
84		return data
85	}
86	
87	// TestRestoreRejectsPendingUnderDeactivatedPolicy 验证核心修复：备份中只要有
88	// 一笔待审批请求关联已停用策略，恢复必须整体失败、不返回钱包，错误可识别为
89	// ErrBackupInvalid 并指出使用账户、请求编号、策略编号与冲突原因。判断只看
90	// 备份保存的状态，与恢复时刻无关：等待期限未到、恰到、早已过去结果相同，
91	// 不会先把该请求自动过期再接受备份。
92	func TestRestoreRejectsPendingUnderDeactivatedPolicy(t *testing.T) {
93		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
94		// r1 提交于 t0-1m，等待截止 t0+4m。
95		for _, tc := range []struct {
96			name      string
97			restoreAt time.Time
98		}{
99			{"wait deadline still in the future", t0.Add(1 * time.Minute)},
100			{"exactly at wait deadline", t0.Add(4 * time.Minute)},
101			{"long after wait deadline", t0.Add(time.Hour)},
102		} {
103			for _, mixed := range []bool{false, true} {
104				name := tc.name
105				if mixed {
106					name += " (other records legal)"
107				}
108				t.Run(name, func(t *testing.T) {
109					data := buildDeactivatedPendingBackup(t, t0, mixed)
110					w2, err := restoreAt(data, tc.restoreAt)
111					if err == nil {
112						if w2 != nil {
113							t.Fatalf("contradictory backup restored a wallet: %+v", w2)
114						}
115						t.Fatal("contradictory backup restored without error")
116					}
117					if !errors.Is(err, ErrBackupInvalid) {
118						t.Fatalf("err = %v, want ErrBackupInvalid", err)
119					}
120					msg := err.Error()
121					for _, want := range []string{"u1", "r1", `"p"`, "deactivated policy", "pending approval"} {
122						if !strings.Contains(msg, want) {
123							t.Fatalf("error %q must identify %q (usage account, request, policy, conflict)", msg, want)
124						}
125					}
126				})
127			}
128		}
129	}
130	
131	// TestRestoreKeepsDeactivatedPolicyWithLegalHistories 验证已停用策略本身及其
132	// 合法历史请求仍可恢复：停用前已批准预留的请求继续保持已预留（可继续结算/
133	// 取消/等待预留超时），停用导致的拒绝保持拒绝，停用前已过期的保持过期，
134	// 首次停用时间、执行账户、理由与账本顺序原样保留，恢复不新增停用或拒绝
135	// 记录；同钱包中未停用策略下的合法待审批请求也照常恢复。
136	func TestRestoreKeepsDeactivatedPolicyWithLegalHistories(t *testing.T) {
137		t.Run("reserved before deactivation stays reserved", func(t *testing.T) {
138			w, c := newTestWallet()
139			t0 := c.t
140			mustAccount(t, w, "payer", 1000)
141			mustAccount(t, w, "u1", 0)
142			if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(time.Hour)); err != nil {
143				t.Fatal(err)
144			}
145			if _, err := w.CreateSession("sa", "payer", "deva", t0.Add(2*time.Hour)); err != nil {
146				t.Fatal(err)
147			}
148			if err := w.SavePolicy(PolicySpec{
149				ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
150				Operation: "charge", Payee: "shop",
151				StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(time.Hour),
152				MaxPerRequest: 100, MaxTotal: 1000,
153				ApprovalThreshold: 10, ApprovalWait: 5 * time.Minute,
154			}); err != nil {
155				t.Fatal(err)
156			}
157			// 超门槛：先待审批，出资账户批准后预留。
158			if _, err := w.Apply(RequestInput{
159				PolicyID: "p", RequestID: "r1", AccountID: "u1", SessionID: "s1",
160				DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 20,
161			}); err != nil {
162				t.Fatal(err)
163			}
164			if _, err := w.Approve("u1", "r1", "sa", "deva"); err != nil {
165				t.Fatal(err)
166			}
167			if _, err := w.DeactivatePolicy("p", "sa", "deva", "stop it"); err != nil {
168				t.Fatal(err)
169			}
170			data, err := w.Export()
171			if err != nil {
172				t.Fatal(err)
173			}
174			// 无论在什么时刻恢复，停用前已预留的请求都保持已预留，停用信息原样保留。
175			for _, at := range []time.Time{t0, t0.Add(4 * time.Minute), t0.Add(time.Hour)} {
176				w2, err := restoreAt(data, at)
177				if err != nil {
178					t.Fatalf("restore at %v: %v", at, err)
179				}
180				r, err := w2.Request("u1", "r1")
181				if err != nil {
182					t.Fatal(err)
183				}
184				if r.State != RequestReserved {
185					t.Fatalf("restore at %v: state = %v, want reserved", at, r.State)
186				}
187				pv, err := w2.Policy("p")
188				if err != nil {
189					t.Fatal(err)
190				}
191				if !pv.Deactivated || pv.DeactivatorAccountID != "payer" || pv.DeactivateReason != "stop it" {
192					t.Fatalf("deactivation info not preserved: %+v", pv)
193				}
194				if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 980, Reserved: 20}) {
195					t.Fatalf("balance after restore = %+v, want 980/20", bal)
196				}
197			}
198			// 恢复不新增账本记录：同刻导出/恢复再导出逐字节一致。
199			w2, err := restoreAt(data, t0)
200			if err != nil {
201				t.Fatal(err)
202			}
203			if got := w2.Ledger(); len(got) != len(w.Ledger()) {
204				t.Fatalf("ledger entries changed: got %d want %d", len(got), len(w.Ledger()))
205			}
206			data2, err := w2.Export()
207			if err != nil {
208				t.Fatal(err)
209			}
210			if string(data) != string(data2) {
211				t.Fatal("restore added records for a legal deactivated-policy backup")
212			}
213		})
214	
215		t.Run("pending rejected by deactivation stays rejected", func(t *testing.T) {
216			w, c := newTestWallet()
217			t0 := c.t
218			mustAccount(t, w, "payer", 1000)
219			mustAccount(t, w, "u1", 0)
220			if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(time.Hour)); err != nil {
221				t.Fatal(err)
222			}
223			if _, err := w.CreateSession("sa", "payer", "deva", t0.Add(2*time.Hour)); err != nil {
224				t.Fatal(err)
225			}
226			if err := w.SavePolicy(PolicySpec{
227				ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
228				Operation: "charge", Payee: "shop",
229				StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(time.Hour),
230				MaxPerRequest: 100, MaxTotal: 1000,
231				ApprovalThreshold: 10, ApprovalWait: 5 * time.Minute,
232			}); err != nil {
233				t.Fatal(err)
234			}
235			if _, err := w.Apply(RequestInput{
236				PolicyID: "p", RequestID: "r1", AccountID: "u1", SessionID: "s1",
237				DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 20,
238			}); err != nil {
239				t.Fatal(err)
240			}
241			// 等待期限内停用：待审批请求随停用立即拒绝。
242			c.t = t0.Add(time.Minute)
243			if _, err := w.DeactivatePolicy("p", "sa", "deva", "stop it"); err != nil {
244				t.Fatal(err)
245			}
246			data, err := w.Export()
247			if err != nil {
248				t.Fatal(err)
249			}
250			// 很久以后恢复：仍是停用拒绝，不追加过期记录、不产生资金变动。
251			w2, err := restoreAt(data, t0.Add(time.Hour))
252			if err != nil {
253				t.Fatalf("restore: %v", err)
254			}
255			r, err := w2.Request("u1", "r1")
256			if err != nil {
257				t.Fatal(err)
258			}
259			if r.State != RequestRejected || !strings.Contains(r.RejectReason, "stop it") {
260				t.Fatalf("request = %+v, want rejected with deactivation reason", r)
261			}
262			if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 1000, Reserved: 0}) {
263				t.Fatalf("balance = %+v, want no funds held", bal)
264			}
265			if got := len(w2.Ledger()); got != len(w.Ledger()) {
266				t.Fatalf("ledger entries changed: got %d want %d", got, len(w.Ledger()))
267			}
268		})
269	
270		t.Run("expired before deactivation stays expired", func(t *testing.T) {
271			w, c := newTestWallet()
272			t0 := c.t
273			mustAccount(t, w, "payer", 1000)
274			mustAccount(t, w, "u1", 0)
275			if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(time.Hour)); err != nil {
276				t.Fatal(err)
277			}
278			if _, err := w.CreateSession("sa", "payer", "deva", t0.Add(2*time.Hour)); err != nil {
279				t.Fatal(err)
280			}
281			if err := w.SavePolicy(PolicySpec{
282				ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
283				Operation: "charge", Payee: "shop",
284				StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(time.Hour),
285				MaxPerRequest: 100, MaxTotal: 1000,
286				ApprovalThreshold: 10, ApprovalWait: 5 * time.Minute,
287			}); err != nil {
288				t.Fatal(err)
289			}
290			if _, err := w.Apply(RequestInput{
291				PolicyID: "p", RequestID: "r1", AccountID: "u1", SessionID: "s1",
292				DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 20,
293			}); err != nil {
294				t.Fatal(err)
295			}
296			// 先等待审批过期，再停用策略：请求保持过期终态。
297			c.t = t0.Add(6 * time.Minute)
298			if r, err := w.Request("u1", "r1"); err != nil || r.State != RequestExpired {
299				t.Fatalf("state = %v err = %v, want expired", r.State, err)
300			}
301			if _, err := w.DeactivatePolicy("p", "sa", "deva", "stop it"); err != nil {
302				t.Fatal(err)
303			}
304			data, err := w.Export()
305			if err != nil {
306				t.Fatal(err)
307			}
308			w2, err := restoreAt(data, c.t.Add(time.Hour))
309			if err != nil {
310				t.Fatalf("restore: %v", err)
311			}
312			r, err := w2.Request("u1", "r1")
313			if err != nil {
314				t.Fatal(err)
315			}
316			if r.State != RequestExpired {
317				t.Fatalf("state = %v, want expired", r.State)
318			}
319			if got := len(w2.Ledger()); got != len(w.Ledger()) {
320				t.Fatalf("ledger entries changed: got %d want %d", got, len(w.Ledger()))
321			}
322		})
323	
324		t.Run("pending under another active policy still restores", func(t *testing.T) {
325			w, c := newTestWallet()
326			t0 := c.t
327			mustAccount(t, w, "payer", 1000)
328			mustAccount(t, w, "u1", 0)
329			if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(time.Hour)); err != nil {
330				t.Fatal(err)
331			}
332			if _, err := w.CreateSession("sa", "payer", "deva", t0.Add(2*time.Hour)); err != nil {
333				t.Fatal(err)
334			}
335			spec := func(id string) PolicySpec {
336				return PolicySpec{
337					ID: id, PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
338					Operation: "charge", Payee: "shop",
339					StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(time.Hour),
340					MaxPerRequest: 100, MaxTotal: 1000,
341					ApprovalThreshold: 10, ApprovalWait: 5 * time.Minute,
342				}
343			}
344			if err := w.SavePolicy(spec("p-off")); err != nil {
345				t.Fatal(err)
346			}
347			if err := w.SavePolicy(spec("p-on")); err != nil {
348				t.Fatal(err)
349			}
350			if _, err := w.DeactivatePolicy("p-off", "sa", "deva", "stop it"); err != nil {
351				t.Fatal(err)
352			}
353			// 未停用策略下的合法待审批请求。
354			if _, err := w.Apply(RequestInput{
355				PolicyID: "p-on", RequestID: "r1", AccountID: "u1", SessionID: "s1",
356				DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 20,
357			}); err != nil {
358				t.Fatal(err)
359			}
360			data, err := w.Export()
361			if err != nil {
362				t.Fatal(err)
363			}
364			// 期限未到：待审批原样恢复，仍可被批准并预留费用。
365			w2, err := restoreAt(data, t0.Add(time.Minute))
366			if err != nil {
367				t.Fatalf("restore: %v", err)
368			}
369			r, err := w2.Request("u1", "r1")
370			if err != nil {
371				t.Fatal(err)
372			}
373			if r.State != RequestPendingApproval {
374				t.Fatalf("state = %v, want pending", r.State)
375			}
376			if _, err := w2.Approve("u1", "r1", "sa", "deva"); err != nil {
377				t.Fatalf("approve after restore: %v", err)
378			}
379			if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 980, Reserved: 20}) {
380				t.Fatalf("balance after approve = %+v, want 980/20", bal)
381			}
382			// 到期时刻恢复：按既有规则自动过期。
383			w3, err := restoreAt(data, t0.Add(6*time.Minute))
384			if err != nil {
385				t.Fatalf("restore at expiry: %v", err)
386			}
387			r3, err := w3.Request("u1", "r1")
388			if err != nil {
389				t.Fatal(err)
390			}
391			if r3.State != RequestExpired {
392				t.Fatalf("state = %v, want expired at restore time", r3.State)
393			}
394		})
395	}
